func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return

	var player := find_by_name(main, "Player") as CharacterBody3D
	if not check("player", player != null, "Nella scena deve esserci il nodo Player"):
		return

	var crystal := find_by_name(main, "CrystalPickup") as Area3D
	if not check("crystal", crystal != null, "Nella scena deve esserci il nodo CrystalPickup"):
		return

	var box := find_by_name(main, "PushBox") as RigidBody3D
	if not check("box", box != null, "Nella scena deve esserci il nodo PushBox"):
		return

	var plate := find_by_name(main, "PressurePlate") as Area3D
	if not check("plate", plate != null, "Nella scena deve esserci il nodo PressurePlate"):
		return

	var gate := find_by_name(main, "PassageGate")
	if not check("gate", gate != null, "Nella scena deve esserci il nodo PassageGate"):
		return

	# 1. Raccolta del cristallo
	player.global_position = crystal.global_position
	await wait_physics_frames(5)
	var crystal_gone: bool = (crystal.get_parent() == null) or crystal.is_queued_for_deletion()
	check("crystal_collected", crystal_gone, "Toccando il cristallo, CrystalPickup deve raccogliersi ed essere rimosso dalla scena con queue_free()")

	# 2. Spinta fisica della cassa
	box.global_position = Vector3(0.0, 2.0, -1.5)
	box.linear_velocity = Vector3.ZERO
	player.global_position = Vector3(0.0, 2.0, -0.6)
	player.velocity = Vector3.ZERO
	await wait_physics_frames(5)

	var start_box_pos: Vector3 = box.global_position
	await hold_action("move_forward", 25)
	if box.global_position.distance_to(start_box_pos) < 0.05:
		player.global_position = Vector3(0.0, 2.0, -0.6)
		await hold_action("move_back", 25)
	await wait_physics_frames(5)
	var box_moved: bool = box.global_position.distance_to(start_box_pos) > 0.05
	check("box_pushed", box_moved, "Camminando contro PushBox, il giocatore deve spingerla applicando un impulso fisico")

	# 3. Attivazione piastra e apertura del passaggio
	box.global_position = plate.global_position + Vector3(0.0, 0.3, 0.0)
	box.linear_velocity = Vector3.ZERO
	player.global_position = Vector3(5.0, 2.0, 0.0)
	await wait_physics_frames(10)

	var is_open: bool = bool(get_prop(main, "is_passage_open", false))
	var gate_col := find_by_class(gate, "CollisionShape3D") as CollisionShape3D
	var gate_disabled: bool = (gate_col != null and gate_col.disabled) or (gate is Node3D and not (gate as Node3D).visible)
	check("passage_opened", is_open or gate_disabled, "Quando la cassa è sulla piastra, il passaggio PassageGate deve aprirsi (is_passage_open = true o collisione disattivata)")

	# 4. Uscita dalla piastra e richiusura del passaggio
	box.global_position = Vector3(30.0, 5.0, 30.0)
	box.linear_velocity = Vector3.ZERO
	await wait_physics_frames(10)

	var is_closed_now: bool = not bool(get_prop(main, "is_passage_open", true))
	var gate_enabled_now: bool = (gate_col != null and not gate_col.disabled)
	check("passage_closed", is_closed_now or gate_enabled_now, "Quando la cassa esce dalla piastra, il passaggio deve richiudersi")
"
